import json,time,subprocess,socket,http.client
def execx(cmd,t=12):
 try:
  r=subprocess.run(cmd,capture_output=True,text=True,timeout=t)
  return {'rc':r.returncode,'stdout':r.stdout.strip()[:170]}
 except Exception as e:return {'rc':99,'error':type(e).__name__}
out={'samples':{},'services':{}}
for n in ('fadego-staging','pink-iptv-backend','pink-vpn','nginx','ssh'):
 out['services'][n]=execx(['systemctl','is-active',n])
for port in (3100,8010):
 a=[]
 for i in range(3):
  row={'tcp':None,'http':None}
  sock=socket.socket(socket.AF_INET,socket.SOCK_STREAM);sock.settimeout(4)
  try:row['tcp']=sock.connect_ex(('127.0.0.1',port))
  except Exception as e:row['tcp']=type(e).__name__
  finally:sock.close()
  try:
   c=http.client.HTTPConnection('127.0.0.1',port,timeout=5)
   c.request('GET','/',headers={'Host':'127.0.0.1'})
   rsp=c.getresponse()
   row['http']=rsp.status
   c.close()
  except Exception as e:row['http']=type(e).__name__
  a.append(row)
  if i!=2:time.sleep(1)
 out['samples'][str(port)]=a
print(json.dumps(out,separators=(',',':')))
